SELECT id, username, real_name, phone_cipher, phone_blind, role_code, dept, status, terminal_limit, auth_method, vlan_id, create_time, update_time FROM sys_user
(username LIKE CONCAT('%', #{keyword}, '%') OR real_name LIKE CONCAT('%', #{keyword}, '%') OR (#{phoneBlind} IS NOT NULL AND phone_blind = #{phoneBlind}))
ORDER BY id ASC LIMIT #{offset}, #{size}
